            # Weather might be keyed by location
            reports = data.get("reports", data.get("locations", {}))
            if isinstance(reports, dict):
                # Find any report with matching conditions
                found = any(
                    r.get("conditions") == expected
                    for r in reports.values()
                    if isinstance(r, dict)
                )
            else:
                found = any(r.get("conditions") == expected for r in reports)
            assert found, f"Weather conditions '{expected}' not found"
        return check

    @staticmethod
    def weather_temperature_range(min_temp: float, max_temp: float) -> AssertionFunc:
        """Assert temperature is within the given range."""
        def check(state: dict[str, Any]) -> None:
            data = state.get("state", state)
            reports = data.get("reports", data.get("locations", {}))
            if isinstance(reports, dict):
                temps = [r.get("temperature") for r in reports.values() if isinstance(r, dict)]
            else:
                temps = [r.get("temperature") for r in reports]
            temps = [t for t in temps if t is not None]
            if not temps:
                raise AssertionError("No temperature data found")
            for temp in temps:
                assert min_temp <= temp <= max_temp, f"Temperature {temp} not in range [{min_temp}, {max_temp}]"
        return check


